namespace ghidra.framework;



using docking;
using docking;
using docking.framework;
using docking.framework;
using docking.widgets;
using generic.theme;
using ghidra.docking.util;
using ghidra.formats.gfilesystem.crypto;
using ghidra.formats.gfilesystem.crypto;
using ghidra.framework.main;
using ghidra.framework.main;
using ghidra.framework.preferences;
using ghidra.net;
using ghidra.util;
using ghidra.util;
using ghidra.util.task;

public class GhidraApplicationConfiguration : HeadlessGhidraApplicationConfiguration {

	private static readonly string USER_AGREEMENT_PROPERTY_NAME = "USER_AGREEMENT";
	private bool showSplashScreen = true;

	public GhidraApplicationConfiguration() {
		if (GraphicsEnvironment.isHeadless()) {
			// NOTE: System.err must be used here because Messaging hasn't been initialized yet
			Console.Error.WriteLine(
				"ERROR: Unable to launch Ghidra GUI application in headless environment.");
			Console.Error.WriteLine(
				"If launching from a remote SSH shell, you must have an X11 compatible client with X11 forwarding enabled.");
			Environment.Exit(1);
		}
	}

	/* @Override */
	public bool isHeadless() {
		return false;
	}

	/* @Override */
	protected void initializeApplication() {
		ApplicationThemeManager.initialize();
		LookAndFeelUtils.performPlatformSpecificFixups();

		if (showSplashScreen) {
			showUserAgreement();
			SplashScreen.showLater();
			this.monitor = new StatusReportingTaskMonitor();
		}

		base.initializeApplication();

		ApplicationKeyManagerFactory
				.setKeyStorePasswordProvider(new PopupKeyStorePasswordProvider());
		CryptoProviders.getInstance().registerCryptoProvider(new PopupGUIPasswordProvider());
	}

	private static void showUserAgreement() {
		string value = Preferences.getProperty(USER_AGREEMENT_PROPERTY_NAME);
		if ("ACCEPT".equals(value)) {
			return;
		}

		SystemUtilities.runSwingNow(() => {
			UserAgreementDialog dialog = new UserAgreementDialog(true, true);
			DockingWindowManager.showDialog(null, dialog);
		});

		// if we get here, then the user has accepted (if not, the system would have exited)
		Preferences.setProperty(USER_AGREEMENT_PROPERTY_NAME, "ACCEPT");
	}

	/* @Override */
	public void installStaticFactories() {
		base.installStaticFactories();
		PluggableServiceRegistry.registerPluggableService(
			typeof(ApplicationInformationDisplayFactory),
			new GhidraApplicationInformationDisplayFactory());
	}

	public void setShowSplashScreen(bool b) {
		showSplashScreen = b;
	}

	/* @Override */
	public ErrorDisplay getErrorDisplay() {
		return new DockingErrorDisplay();
	}

	private static class StatusReportingTaskMonitor : TaskMonitorAdapter {
		/* @Override */
		public void setCancelEnabled(bool enable) {
			// Not permitted
		}

		/* @Override */
		public void setMessage(string message) {
			SplashScreen.updateSplashScreenStatus(message);
		}
	}

}
